<?php

declare(strict_types=1);

namespace MailjetSDK\DTOs\Output;

final class Contactslist extends \MailjetSDK\DTOs\Base\Contactslist
{
    public const array REQUIRED_FIELDS = [];

    /**
     * Unique email address generated by Mailjet, which can be used only via Mailjet's SMTP server to reach all contacts in the list. The full address will be `{address}&#64;lists.mailjet.com`.
     */
    public string $Address;
    /**
     * Timestamp of when the contact list was created.
     */
    public string $CreatedAt;
    /**
     * Unique numeric ID assigned to this contact list.
     */
    public int $ID;
    /**
     * Number of contacts registered in this contact list. Includes contacts that were unsubscribed from the list, as well as excluded ones.
     */
    public int $SubscriberCount;

    protected function assignMember(string $name, mixed $value): void
    {
        match ($name) {
            'Address' => is_string($value) ? $this->Address = $value : parent::assignMember($name, $value),
            'CreatedAt' => is_string($value) ? $this->CreatedAt = $value : parent::assignMember($name, $value),
            'ID' => is_int($value) ? $this->ID = $value : parent::assignMember($name, $value),
            'SubscriberCount' => is_int($value) ? $this->SubscriberCount = $value : parent::assignMember($name, $value),
            default => parent::assignMember($name, $value),
        };
    }
}
